const mapCenters={amazonas:{center:[-2.15,-71.72],zoom:6},leticia:{center:[-4.215,-69.94],zoom:11},'puerto-narino':{center:[-3.77,-70.38],zoom:11}};
const geoSources=window.CARTOGRAFIA_FUENTES?.sources||[];
let toastTimer = null;
function toast(message){const el=document.getElementById('toast');if(!el)return;el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,3200);}
function viewRoute(){
  const desired=location.hash.replace(/^#/,'') || 'inicio';
  const route=routes.has(desired)?desired:'inicio';
  document.querySelectorAll('.view').forEach(el=>el.classList.toggle('active',el.dataset.view===route));
  document.querySelectorAll('.nav-link').forEach(el=>{const active=el.dataset.route===route;el.classList.toggle('active',active);if(active){el.setAttribute('aria-current','page')}else{el.removeAttribute('aria-current')}});
  document.getElementById('top-nav').classList.remove('is-open');
  document.getElementById('nav-toggle').setAttribute('aria-expanded','false');
  window.scrollTo({top:0,behavior:'instant'});
  window.POD_PUBLICACION.titulo(route==='inicio'?'Observatorio Departamental del Amazonas':(document.querySelector(`#view-${route} h1`)?.textContent || route)+' · Observatorio Departamental del Amazonas');
  if(route==='geovisor')setTimeout(initMap,90);
}
function initMap(){
  if(mapInstance){mapInstance.invalidateSize();window.obs19MapReady?.();return;}
  const el=document.getElementById('visor-map');
  if(!window.L||!el){toast('Para usar el mapa interactivo se necesita conexión a internet.');return;}
  el.innerHTML='';
  mapInstance=L.map(el,{zoomControl:true,scrollWheelZoom:false}).setView(mapCenters.amazonas.center,mapCenters.amazonas.zoom);
  baseLayer=L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{
    maxZoom:18,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors'
  }).addTo(mapInstance);
  L.control.scale({imperial:false}).addTo(mapInstance);
  L.circleMarker(mapCenters.leticia.center,{radius:6,weight:2,color:'#176d42',fillColor:'#bedeba',fillOpacity:.9})
    .bindPopup('Leticia · Punto orientativo (no corresponde a una capa oficial del POD)').addTo(mapInstance);
  window.obs19MapReady?.();
  mapInstance.on('click',event=>{
    if(mapMode==='measure'){
      measurePoints.push(event.latlng);
      measureMarkers.push(L.circleMarker(event.latlng,{radius:4,color:'#b26f10',weight:2,fillColor:'#fbd79c',fillOpacity:1}).addTo(mapInstance));
      if(measurePolyline)mapInstance.removeLayer(measurePolyline);
      measurePolyline=L.polyline(measurePoints,{color:'#b26f10',weight:3,dashArray:'7 5'}).addTo(mapInstance);
      let total=0;for(let i=1;i<measurePoints.length;i++)total+=measurePoints[i-1].distanceTo(measurePoints[i]);
      document.getElementById('map-measure-distance').textContent=measurePoints.length<2?'Selecciona otro punto para medir.':`Distancia aproximada: ${total<1000?Math.round(total)+' m':(total/1000).toFixed(2).replace('.',',')+' km'}`;
      document.getElementById('clear-measure').disabled=false;
    }else{
      const {lat,lng}=event.latlng;
      lastCoords={lat:lat.toFixed(6),lng:lng.toFixed(6)};
      document.getElementById('map-coordinate').textContent=`Latitud ${lastCoords.lat} · Longitud ${lastCoords.lng} (WGS84)`;
      document.getElementById('copy-coordinates').disabled=false;
    }
  });
}
function selectMapMode(mode){
  mapMode=mode;
  document.getElementById('map-inspect').classList.toggle('active',mode==='inspect');
  document.getElementById('measure-mode').classList.toggle('active',mode==='measure');
  document.getElementById('map-inspect').setAttribute('aria-pressed',mode==='inspect'?'true':'false');
  document.getElementById('measure-mode').setAttribute('aria-pressed',mode==='measure'?'true':'false');
  document.getElementById('map-mode-hint').textContent=mode==='measure'?'Haz clic en dos o más puntos para medir una distancia orientativa.':'Haz clic en el mapa para obtener coordenadas.';
  document.getElementById('visor-map').classList.toggle('measure-mode',mode==='measure');
}
function clearMeasure(){
  if(!mapInstance)return;
  if(measurePolyline)mapInstance.removeLayer(measurePolyline);
  measureMarkers.forEach(m=>mapInstance.removeLayer(m));
  measurePolyline=null;measurePoints=[];measureMarkers=[];
  document.getElementById('map-measure-distance').textContent='';
  document.getElementById('clear-measure').disabled=true;
}
function chooseGeoCategory(name){
  selectedGeoCategory=selectedGeoCategory===name?null:name;
  drawGeoLayerList();
  if(selectedGeoCategory)toast(`Temática seleccionada: ${name}. Aún no hay capas oficiales publicadas.`);
}
function drawGeoLayerList(){
  const mount=document.getElementById('geo-layer-list');
  mount.innerHTML=categories.map(c=>`<div><button type="button" class="geo-cat-button ${selectedGeoCategory===c.name?'active':''}" data-geo-category="${libEscape(c.name)}" aria-expanded="${selectedGeoCategory===c.name?'true':'false'}">${icon(c.icon)}<span class="geo-cat-label">${libEscape(c.name)}</span><span class="geo-count">0 capas</span></button>${selectedGeoCategory===c.name?`<ul class="geo-topic-list">${c.topics.map(t=>`<li>${libEscape(t)}</li>`).join('')}</ul>`:''}</div>`).join('');
  mount.querySelectorAll('[data-geo-category]').forEach(b=>b.addEventListener('click',()=>chooseGeoCategory(b.dataset.geoCategory)));
}
function drawCategories(filter=''){
  const q=normalizeLibrary(filter.trim());
  const matched=categories.filter(c=>normalizeLibrary(c.name+' '+c.description+' '+c.topics.join(' ')).includes(q));
  const grid=document.getElementById('categories-grid');
  if(!matched.length){grid.innerHTML='<p>No hay categorías que coincidan con tu búsqueda.</p>';return;}
  grid.innerHTML=matched.map(c=>`<article class="category-card"><div class="cat-head"><div class="cat-icon">${icon(c.icon)}</div><h3>${libEscape(c.name)}</h3></div><p>${libEscape(c.description)}</p><div class="cat-chips">${c.topics.map(t=>`<span>${libEscape(t)}</span>`).join('')}</div><span class="cat-pending">Sin capas oficiales publicadas</span><button type="button" class="geo-cat-action" data-open-theme="${libEscape(c.name)}">Explorar temática →</button></article>`).join('');
  grid.querySelectorAll('[data-open-theme]').forEach(b=>b.addEventListener('click',()=>{selectedGeoCategory=b.dataset.openTheme;drawGeoLayerList();location.hash='#geovisor';}));
}
function drawGeoSources(){
 const mount=document.getElementById('geo-sources');if(!mount)return;
 mount.innerHTML=geoSources.map(s=>`<article class="geo-source-card"><small>${libEscape(s.kind)}</small><h3>${libEscape(s.name)}</h3><p>${libEscape(s.origin)} · ${libEscape(s.note)}</p><a href="${safeDriveFolderUrl(s.url)}" target="_blank" rel="noopener noreferrer">Abrir carpeta en Drive ↗</a></article>`).join('');
}
function safeDriveFolderUrl(link){
  try{const u=new URL(String(link||''));return u.protocol==='https:'&&u.hostname==='drive.google.com'&&/^\/drive\/folders\/[A-Za-z0-9_-]+$/.test(u.pathname)?u.href:'#';}catch(_error){return '#';}
}
/* Gestión de archivos GeoJSON del navegador; no se publican como cartografía oficial. */
function v7FeatureHtml(feature,entry){
  const props=feature&&feature.properties&&typeof feature.properties==='object'?Object.entries(feature.properties).slice(0,20):[];
  const cells=props.map(([k,v])=>{
    let value=typeof v==='object'?(v===null?'—':JSON.stringify(v)):String(v===undefined?'—':v);
    return `<tr><td>${libEscape(k)}</td><td>${libEscape(value.slice(0,550))}</td></tr>`;
  }).join('');
  return `<strong>${libEscape(entry.name)}</strong><div style="font-size:10px;margin:3px 0 5px;color:#8a5945">Archivo cargado en este navegador · no constituye información oficial</div>${cells?`<table>${cells}</table>`:'Este elemento no tiene atributos.'}`;
}
function v7FormatBytes(n){return n<1048576?`${Math.max(1,Math.round(n/1024))} KB`:`${(n/1048576).toFixed(1)} MB`;}
function v7GeomType(data){
  let geom=(data.type==='FeatureCollection'?data.features?.find(f=>f&&f.geometry)?.geometry:data.type==='Feature'?data.geometry:data);
  let typ=geom?.type||'Geometry';
  if(/Point/.test(typ))return 'Puntos';if(/LineString/.test(typ))return 'Líneas';if(/Polygon/.test(typ))return 'Polígonos';return 'Geometrías mixtas';
}
function v7RenderLayers(){
  const searched=normalizeLibrary(document.getElementById('layer-filter').value.trim());
  const mount=document.getElementById('local-layer-list');
  // Las capas temáticas tienen sus controles únicos en el menú del POD.
  const localLayers=importedLayers.filter(e=>e.idPilot==null&&e.idCitizen==null);
  let filtered=localLayers.filter(e=>normalizeLibrary(e.name).includes(searched));
  mount.innerHTML=filtered.length?filtered.map(e=>`<div class="v7-imported-layer" data-local-layer="${e.id}">
    <div class="v7-layer-main"><input aria-label="Mostrar ${libEscape(e.name)}" type="checkbox" data-toggle-layer="${e.id}" ${e.visible?'checked':''}/>
    <span class="v7-swatch" style="color:${e.color};background:${e.color}38"></span>
    <div style="min-width:0;flex:1"><div class="v7-layer-name">${libEscape(e.name)}</div><div class="v7-layer-meta">${e.count} entidades · ${libEscape(e.geomType)} · ${libEscape(e.origin)}</div></div></div>
    <label class="obs19-opacity-line">Transparencia del polígono <input type="range" min="0" max="100" value="${100-e.opacity}" data-opacity-layer="${e.id}" aria-label="Transparencia de ${libEscape(e.name)} (0% sólido; 100% invisible)"><small>${100-e.opacity}%</small></label>
    <div class="v7-layer-tools"><button type="button" data-zoom-layer="${e.id}">Zoom a capa</button><button type="button" class="danger" data-remove-layer="${e.id}">Quitar</button></div>
  </div>`).join(''):'<div class="local-layer-summary">'+(localLayers.length?'Ninguna capa coincide con tu búsqueda.':'Todavía no has cargado capas locales.')+'</div>';
  document.getElementById('local-layer-summary').textContent=`${localLayers.length} archivo${localLayers.length===1?'':'s'} cargado${localLayers.length===1?'':'s'} en este navegador · ${localLayers.filter(e=>e.visible).length} visible${localLayers.filter(e=>e.visible).length===1?'':'s'}`;
  document.getElementById('geojson-reset').disabled=!importedLayers.length;
  const legend=document.getElementById('v7-dynamic-legend');
  legend.innerHTML=importedLayers.filter(e=>e.visible).map(e=>`<div class="v7-legend-tag" title="${libEscape(e.name)}"><i class="v7-swatch" style="color:${e.color};background:${e.color}33"></i><span>${libEscape(e.name)}</span></div>`).join('');
  mount.querySelectorAll('[data-opacity-layer]').forEach(sl=>sl.addEventListener('input',()=>{const e=importedLayers.find(x=>x.id===Number(sl.dataset.opacityLayer));if(!e)return;e.opacity=100-Number(sl.value);e.layer.setStyle?.({fillOpacity:e.opacity/100*(e.geomType==='Puntos'?1:.52)});sl.nextElementSibling.textContent=sl.value+'%';window.obs19RenderStats?.();}));
  window.obs19RenderStats?.();
  mount.querySelectorAll('[data-toggle-layer]').forEach(el=>el.addEventListener('change',()=>v7ToggleLayer(Number(el.dataset.toggleLayer),el.checked)));
  mount.querySelectorAll('[data-remove-layer]').forEach(el=>el.addEventListener('click',()=>v7RemoveLayer(Number(el.dataset.removeLayer))));
  mount.querySelectorAll('[data-zoom-layer]').forEach(el=>el.addEventListener('click',()=>v7ZoomLayer(Number(el.dataset.zoomLayer))));
}
function v7ToggleLayer(id,show){
 const e=importedLayers.find(e=>e.id===id);if(!e||!mapInstance)return;
 e.visible=show;if(show){e.layer.addTo(mapInstance)}else{mapInstance.removeLayer(e.layer)}v7RenderLayers();
}
function v7ZoomLayer(id){const e=importedLayers.find(e=>e.id===id);if(!e||!mapInstance)return;if(!e.visible){e.visible=true;e.layer.addTo(mapInstance);}
  let bounds=e.layer.getBounds();if(bounds.isValid())mapInstance.fitBounds(bounds.pad(.15),{maxZoom:13});v7RenderLayers();}
function v7RemoveLayer(id){
 const idx=importedLayers.findIndex(e=>e.id===id);if(idx<0)return;
 if(mapInstance)mapInstance.removeLayer(importedLayers[idx].layer);
 importedLayers.splice(idx,1);v7RenderLayers();
 document.getElementById('geo-attribute-info').textContent='Haz clic en un elemento de una capa para ver sus atributos aquí.';
}
function v7ValidateGeoJSON(data){
 if(!data||typeof data!=='object'||!['FeatureCollection','Feature','Point','MultiPoint','LineString','MultiLineString','Polygon','MultiPolygon','GeometryCollection'].includes(data.type))throw new Error('No es GeoJSON válido.');
 const features=data.type==='FeatureCollection'?data.features:data.type==='Feature'?[data]:[{type:'Feature',properties:{},geometry:data}];
 if(!Array.isArray(features)||features.length===0)throw new Error('No contiene entidades.');
 if(features.length>3000)throw new Error('Se admiten como máximo 3000 entidades por archivo.');
 if(features.some(f=>!f||f.type!=='Feature'||(!f.geometry&&f.geometry!==null)))throw new Error('Contiene entidades GeoJSON incorrectas.');
 return features.length;
}
function v7AddGeoJSON(name,data,origin='archivo local',zoom=true){
 if(!mapInstance||!window.L)throw new Error('El mapa todavía no está disponible.');
 if(importedLayers.length>=8)throw new Error('Ya se alcanzó el máximo de 8 capas.');
 const count=v7ValidateGeoJSON(data);const id=nextImportedLayerId++;
 const color=layerColors[(id-1)%layerColors.length];
 const entry={id,name,count,color,origin,visible:true,opacity:65,data,geomType:v7GeomType(data),layer:null};
 const candidate=L.geoJSON(data,{
  style:()=>({color,weight:3,fillColor:color,fillOpacity:.22}),
  pointToLayer:(feature,latlng)=>L.circleMarker(latlng,{radius:9,color:'#fff',weight:2.5,fillColor:color,fillOpacity:1}),
  onEachFeature:(feature,layer)=>{
    const html=v7FeatureHtml(feature,entry);
    layer.bindPopup(`<div style="min-width:180px;max-width:280px">${html}</div>`);
    layer.on('click',()=>{const target=document.getElementById('geo-attribute-info');target.innerHTML=html;window.obs19SelectLayer?.(entry.id);});
    const pointName=String(feature.properties?.nombre||feature.properties?.name||feature.properties?.NOMBRE||'').trim();
    if(feature.geometry?.type==='Point'&&pointName&&count<=15){layer.bindTooltip(libEscape(pointName.slice(0,80)),{permanent:true,direction:'top',offset:[0,-13],className:'local-geojson-tooltip'});}
  }
 });
 if(!candidate.getLayers().length)throw new Error('No se encontraron geometrías representables.');
 entry.layer=candidate;candidate.addTo(mapInstance);importedLayers.push(entry);
 if(zoom){let b=candidate.getBounds();if(b.isValid())mapInstance.fitBounds(b.pad(.18),{maxZoom:12});}
 v7RenderLayers();return entry;
}
async function loadLocalGeojson(event){
 const files=[...(event.target.files||[])];if(!files.length)return;
 let ok=0,errors=[];
 for(const f of files){
  try{
   if(f.size>15*1024*1024)throw new Error('supera 15 MB');
   const data=JSON.parse(await f.text());v7AddGeoJSON(f.name,data,'archivo local',true);ok++;
  }catch(err){errors.push(`${f.name}: ${err.message}`);}
 }
 if(errors.length){document.getElementById('local-layer-summary').textContent=`Importadas: ${ok}. No se pudo cargar: ${errors.slice(0,3).join(' · ')}`;toast('Algunos archivos no pudieron cargarse.');}
 else toast(`${ok} capa${ok===1?'':'s'} importada${ok===1?'':'s'}. No se ha publicado ningún archivo.`);
 event.target.value='';
}
function removeLocalGeojson(){
 importedLayers.forEach(e=>mapInstance?.removeLayer(e.layer));importedLayers=[];
 document.getElementById('layer-filter').value='';
 document.getElementById('geo-attribute-info').textContent='Haz clic en un elemento de una capa para ver sus atributos aquí.';
 v7RenderLayers();toast('Capas locales eliminadas.');
}
function v7LoadDemo(){
  if(!mapInstance||!window.L){toast('Espera a que se cargue el mapa.');return;}
  const a={type:'FeatureCollection',features:[
    {type:'Feature',properties:{nombre:'Leticia · referencia aproximada',tipo:'Punto ilustrativo',fuente:'Ejemplo didáctico no oficial'},geometry:{type:'Point',coordinates:[-69.94,-4.215]}},
    {type:'Feature',properties:{nombre:'Puerto Nariño · referencia aproximada',tipo:'Punto ilustrativo',fuente:'Ejemplo didáctico no oficial'},geometry:{type:'Point',coordinates:[-70.38,-3.77]}}
  ]};
  const b={type:'FeatureCollection',features:[
    {type:'Feature',properties:{nombre:'Trazo ficticio de prueba',nota:'No es una vía, ruta ni río real'},geometry:{type:'LineString',coordinates:[[-70.38,-3.77],[-70.17,-3.98],[-69.94,-4.215]]}}
  ]};
  const c={type:'FeatureCollection',features:[
    {type:'Feature',properties:{nombre:'Polígono didáctico',nota:'Zona ficticia para comprobar atributos y leyendas, no constituye delimitación territorial'},geometry:{type:'Polygon',coordinates:[[[-70.03,-4.26],[-69.97,-4.26],[-69.97,-4.22],[-70.03,-4.22],[-70.03,-4.26]]]}}
  ]};
  let added=0;for(const [name,data] of [['Puntos de referencia · DEMO',a],['Línea de prueba · DEMO',b],['Polígono ficticio · DEMO',c]]){
    if(importedLayers.some(e=>e.name===name))continue;
    try{v7AddGeoJSON(name,data,'demostración',false);added++;}catch(err){toast(err.message);break;}
  }
  if(added){mapInstance.fitBounds([[-4.32,-70.44],[-3.72,-69.87]],{maxZoom:11});toast(`${added} capas de demostración cargadas (no oficiales).`)}
  else toast('Las capas de demostración ya estaban cargadas.');
}
/* Biblioteca: catálogo inicial exportado de Drive. No usa la API en vivo. */
function normalizeLibrary(text){return String(text??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es');}
function libEscape(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}
function libSelectedCategory(cat){libraryCategory=cat;libraryLimit=10;drawLibrary();}
function drawLibrary(){
 const select=document.getElementById('library-scope'); if(!select)return;
 const previous=select.value || libraryScope;
 const scopes=[...new Set(libraryData.documents.filter(d=>libraryCategory==='Todas'||d.category===libraryCategory).map(d=>d.scope))].sort((a,b)=>a.localeCompare(b,'es'));
 select.innerHTML='<option value="Todas">Todas las escalas</option>'+scopes.map(s=>`<option value="${libEscape(s)}">${libEscape(s)}</option>`).join('');
 select.value=scopes.includes(previous)?previous:'Todas'; libraryScope=select.value;
 const cats=document.getElementById('library-grid');
 cats.innerHTML=libraryData.categories.map(c=>{
  const total=libraryData.documents.filter(d=>d.category===c.id).length;
  return `<button type="button" class="library-item ${libraryCategory===c.id?'selected':''}" data-library="${libEscape(c.id)}" aria-pressed="${libraryCategory===c.id}">${icon(c.icon)}<strong>${libEscape(c.name)}</strong><span>${c.id==='cartografia'?'Explorar carpetas geográficas':`${total} documentos del catálogo`}</span></button>`;
 }).join('');
 cats.querySelectorAll('[data-library]').forEach(b=>b.addEventListener('click',()=>libSelectedCategory(libraryCategory===b.dataset.library?'Todas':b.dataset.library)));
 const query=normalizeLibrary(document.getElementById('library-search').value.trim());
 let docs=libraryData.documents.filter(d=>(libraryCategory==='Todas'||d.category===libraryCategory)&&(libraryScope==='Todas'||d.scope===libraryScope)&&normalizeLibrary(d.name+' '+d.scope+' '+(libraryData.categories.find(c=>c.id===d.category)?.name||'')).includes(query));
 docs.sort((a,b)=>a.name.localeCompare(b.name,'es'));
 const visible=docs.slice(0,libraryLimit);
 document.getElementById('library-results').textContent=`Mostrando ${visible.length} de ${docs.length} documentos del catálogo actual`;
 document.getElementById('library-total').textContent=libraryData.documents.length;
 document.getElementById('library-cats-count').textContent=libraryData.categories.length;
 const mount=document.getElementById('library-doc-list');
 mount.innerHTML=visible.length?visible.map(d=>{
  const cat=libraryData.categories.find(c=>c.id===d.category);
  return `<article class="pod-document"><span class="pod-doc-icon">${icon('file')}</span><div class="pod-doc-info"><h3>${libEscape(d.name)}</h3><p><span>${libEscape(cat?.name||'')}</span><span>·</span><span>${libEscape(d.scope)}</span></p><div class="pod-doc-metadata"><span>${libEscape(d.format || 'PDF')}</span><span>${formatPodSize(d.sizeBytes || 0)}</span><span>Fuente: Google Drive</span></div></div><div class="pod-doc-actions"><a class="pod-view-link" href="${safeDriveUrl(d.url)}" target="_blank" rel="noopener noreferrer">Abrir archivo ${icon('external')}</a></div></article>`;
 }).join(''):'<div class="pod-empty"><h3>No se encontraron archivos con estos filtros</h3><p>Intenta con otro filtro o abre la carpeta de Google Drive para consultar el repositorio completo.</p></div>';
 const more=document.getElementById('library-more');more.hidden=libraryLimit>=docs.length;
 const links=document.getElementById('library-folder-links');
 links.innerHTML=libraryData.categories.filter(c=>libraryCategory==='Todas'||c.id===libraryCategory).map(c=>`<article class="library-source-card"><div class="library-source-card-head"><strong>${libEscape(c.name)}</strong><a href="${c.url}" target="_blank" rel="noopener noreferrer">Abrir categoría ↗</a></div><div class="library-folder-list">${c.folders.map(f=>`<a href="${f.url}" target="_blank" rel="noopener noreferrer">${libEscape(f.name)} ↗</a>`).join('')}</div></article>`).join('');
}
/* POD catalog: snapshot from a read-only inventory of Google Drive, not a live API. */
const podInventory = window.POD_CATALOGO || {documents:[],folders:[]};
let podPhase='Todas', podLimit=12;
function escapePod(text){return String(text??'').replace(/[&<>"']/g, m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}
function normalizePod(text){return String(text??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es');}
function formatPodSize(bytes){return bytes>=1048576?`${(bytes/1048576).toFixed(1).replace('.',',')} MB`:`${Math.max(1,Math.round(bytes/1024))} KB`;}
function setPodPhase(phase){podPhase=phase;podLimit=12;drawPodTabs();drawPodSubfolders();drawPodDocuments();}
function drawPodTabs(){
 const mount=document.getElementById('pod-phase-tabs');if(!mount)return;
 const values=['Todas',...podInventory.folders.map(f=>f.name)];
 mount.innerHTML=values.map((phase,i)=>{
   const count=phase==='Todas'?podInventory.documents.length:podInventory.documents.filter(d=>d.phase===phase).length;
   return `<button type="button" class="pod-phase-tab ${phase===podPhase?'selected':''}" data-pod-phase="${escapePod(phase)}" aria-pressed="${phase===podPhase}"><span>${i===0?'Todo':`0${i}`}</span><strong>${escapePod(phase==='Todas'?'Todas':phase)}</strong><small>${count} PDF</small></button>`;
 }).join('');
 mount.querySelectorAll('[data-pod-phase]').forEach(b=>b.addEventListener('click',()=>setPodPhase(b.dataset.podPhase)));
}
function drawPodSubfolders(){
 const select=document.getElementById('pod-subfolder');if(!select)return;
 const subset=podInventory.documents.filter(d=>podPhase==='Todas'||d.phase===podPhase);
 const folders=[...new Set(subset.map(d=>d.subfolder))].sort((a,b)=>a.localeCompare(b,'es'));
 const current=select.value;
 select.innerHTML='<option value="Todas">Todas las subcarpetas</option>'+folders.map(s=>`<option value="${escapePod(s)}">${escapePod(s)}</option>`).join('');
 select.value=folders.includes(current)?current:'Todas';
}
function getPodVisible(){
 const needle=normalizePod(document.getElementById('pod-search').value.trim());
 const sub=document.getElementById('pod-subfolder').value;
 const sort=document.getElementById('pod-sort').value;
 let items=podInventory.documents.filter(d=>(podPhase==='Todas'||d.phase===podPhase)&& (sub==='Todas'||d.subfolder===sub)&&normalizePod(d.name+' '+d.phase+' '+d.subfolder).includes(needle));
 if(sort==='name')items.sort((a,b)=>a.name.localeCompare(b.name,'es'));
 if(sort==='size')items.sort((a,b)=>b.sizeBytes-a.sizeBytes);
 return items;
}
function drawPodDocuments(){
 const mount=document.getElementById('pod-doc-list');if(!mount)return;
 const items=getPodVisible();const visible=items.slice(0,podLimit);
 const count=document.getElementById('pod-results-caption');
 count.textContent=`Mostrando ${visible.length} de ${items.length} documentos que coinciden con los filtros`;
 if(!items.length){mount.innerHTML='<div class="pod-empty"><h3>No encontramos documentos con esos filtros</h3><p>Intenta con otra palabra o selecciona una carpeta diferente.</p></div>';}else{
   mount.innerHTML=visible.map(d=>`<article class="pod-document">
     <span class="pod-doc-icon" aria-hidden="true">${icon('file')}</span>
     <div class="pod-doc-info"><h3>${escapePod(d.name)}</h3><p><span>${escapePod(d.phase)}</span><span aria-hidden="true">·</span><span>${escapePod(d.subfolder)}</span></p><div class="pod-doc-metadata"><span>PDF</span><span>${formatPodSize(d.sizeBytes)}</span></div></div>
     <div class="pod-doc-actions"><a class="pod-view-link" href="${safeDriveUrl(d.url)}" target="_blank" rel="noopener noreferrer" aria-label="Abrir ${escapePod(d.name)} en Google Drive">Abrir en Drive ${icon('external')}</a></div>
   </article>`).join('');
 }
 const more=document.getElementById('pod-show-more');more.hidden=items.length<=podLimit;
 document.getElementById('pod-folder-links').innerHTML=podInventory.folders.map(f=>`<a target="_blank" rel="noopener noreferrer" href="${f.url}"><strong>${escapePod(f.name)}</strong><small>Abrir carpeta en Google Drive ↗</small></a>`).join('');
}
function drawPodCatalog(){
 const docs=podInventory.documents;
 document.getElementById('pod-total').textContent=docs.length;
 document.getElementById('pod-openable').textContent=docs.length;
 drawPodTabs();drawPodSubfolders();drawPodDocuments();
 document.getElementById('pod-search').addEventListener('input',()=>{podLimit=12;drawPodDocuments();});
 document.getElementById('pod-subfolder').addEventListener('change',()=>{podLimit=12;drawPodDocuments();});
 document.getElementById('pod-sort').addEventListener('change',()=>{podLimit=12;drawPodDocuments();});
 document.getElementById('pod-show-more').addEventListener('click',()=>{podLimit+=12;drawPodDocuments();});
}
function previewCertificate(e){
  e.preventDefault();
  const name=document.getElementById('project-name').value.trim();
  const sector=document.getElementById('project-sector').value;
  const lat=document.getElementById('project-lat').value;
  const lon=document.getElementById('project-lon').value;
  if(!name||lat===''||lon===''){toast('Completa los campos de la solicitud');return;}
  const result=document.getElementById('certificate-result');
  result.innerHTML='<h3>Vista previa generada localmente</h3><p id="preview-title"></p><p id="preview-coords"></p><p><strong>Estado:</strong> No radicado · Sin verificación cartográfica · Sin validez oficial.</p>';
  result.querySelector('#preview-title').textContent=`Proyecto: ${name} · Sector: ${sector}`;
  result.querySelector('#preview-coords').textContent=`Ubicación declarada: latitud ${lat}, longitud ${lon}`;
  result.hidden=false;
  toast('Vista previa creada. Ningún dato fue enviado.');
}
async function copyCoords(){
  if(!lastCoords)return;
  const content=`${lastCoords.lat}, ${lastCoords.lng}`;
  try{await navigator.clipboard.writeText(content);toast('Coordenadas copiadas');}catch(e){toast(`Coordenadas: ${content}`);}
}
function updateSyncStatus(){
 const labels=[['pod-sync-status',podInventory],['library-sync-status',libraryData]];
 labels.forEach(([id,data])=>{
   const el=document.getElementById(id); if(!el)return;
   if(data?.syncMode==='live' && data.syncedAt){
     const when=new Date(data.syncedAt);
     el.textContent='Catálogo generado desde Google Drive: '+ (Number.isNaN(when.getTime())?data.syncedAt:when.toLocaleString('es-CO'))+'. Las nuevas publicaciones requieren revisión institucional.';
   }else{
     el.textContent='Catálogo de referencia: la actualización automática con Google Drive aún no está activada.';
   }
 });
}
window.obs19Api={getMap:()=>mapInstance,getLayers:()=>importedLayers,add:v7AddGeoJSON,remove:v7RemoveLayer,zoom:v7ZoomLayer,redraw:v7RenderLayers};
function boot(){
  updateSyncStatus();
  drawGeoLayerList();drawCategories();drawGeoSources();drawLibrary();drawPodCatalog();
  document.getElementById('catalog-search').addEventListener('input',e=>drawCategories(e.target.value));
  document.getElementById('library-search').addEventListener('input',()=>{libraryLimit=10;drawLibrary();});
  document.getElementById('library-scope').addEventListener('change',e=>{libraryScope=e.target.value;libraryLimit=10;drawLibrary();});
  document.getElementById('library-clear').addEventListener('click',()=>{document.getElementById('library-search').value='';libraryCategory='Todas';libraryScope='Todas';libraryLimit=10;drawLibrary();});
  document.getElementById('library-more').addEventListener('click',()=>{libraryLimit+=10;drawLibrary();});
  /* Certificados utiliza su asistente independiente. */
  document.getElementById('admin-entry').addEventListener('click',()=>{location.hash='#admin';toast('Vista de demostración: no hay inicio de sesión activo');});
  document.getElementById('nav-toggle').addEventListener('click',()=>{
    const menu=document.getElementById('top-nav');const opened=menu.classList.toggle('is-open');
    document.getElementById('nav-toggle').setAttribute('aria-expanded',opened?'true':'false');
  });
  document.getElementById('reset-map').addEventListener('click',()=>{if(mapInstance){mapInstance.setView(mapCenters.amazonas.center,mapCenters.amazonas.zoom);document.getElementById('map-location-select').value='amazonas';toast('Mapa centrado en el Amazonas');}else{toast('Se necesita conexión para cargar el mapa base');}});
  document.getElementById('basemap-toggle').addEventListener('change',e=>{
    if(!mapInstance||!baseLayer){e.target.checked=true;toast('El mapa base aún no está disponible');return;}
    if(e.target.checked){baseLayer.addTo(mapInstance);}else{mapInstance.removeLayer(baseLayer);}
  });
  document.getElementById('copy-coordinates').addEventListener('click',copyCoords);
  document.getElementById('map-location-select').addEventListener('change',e=>{const place=mapCenters[e.target.value];if(!place)return;if(mapInstance){mapInstance.setView(place.center,place.zoom);toast('Mapa centrado en la ubicación seleccionada');}else{toast('Mapa base no disponible sin conexión');}});
  document.getElementById('map-inspect').addEventListener('click',()=>selectMapMode('inspect'));
  document.getElementById('measure-mode').addEventListener('click',()=>selectMapMode('measure'));
  document.getElementById('clear-measure').addEventListener('click',clearMeasure);
  document.getElementById('geojson-upload').addEventListener('change',loadLocalGeojson);
  document.getElementById('geojson-reset').addEventListener('click',removeLocalGeojson);
  document.getElementById('load-demo-layers').addEventListener('click',v7LoadDemo);
  document.getElementById('layer-filter').addEventListener('input',v7RenderLayers);
  v7RenderLayers();
  window.addEventListener('hashchange',viewRoute);
  viewRoute();
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();

